// ABOUTME: Journal search functionality with vector similarity and text matching
// ABOUTME: Provides unified search across project and user journal entries

import * as fs from 'fs/promises';
import * as path from 'path';
import { EmbeddingService, EmbeddingData } from './embeddings.js';
import { resolveUserJournalPath, resolveProjectJournalPath } from './paths.js';

export interface SearchResult {
  path: string;
  score: number;
  text: string;
  sections: string[];
  timestamp: number;
  excerpt: string;
  type: 'project' | 'user';
}

export interface RecentEntryResult {
  path: string;
  content: string;
  sections: string[];
  timestamp: number;
  type: 'project' | 'user';
}

export interface SearchOptions {
  limit?: number;
  minScore?: number;
  sections?: string[];
  dateRange?: {
    start?: Date;
    end?: Date;
  };
  type?: 'project' | 'user' | 'both';
}

export class SearchService {
  private embeddingService: EmbeddingService;
  private projectPath: string;
  private userPath: string;

  constructor(projectPath?: string, userPath?: string) {
    this.embeddingService = EmbeddingService.getInstance();
    this.projectPath = projectPath || resolveProjectJournalPath();
    this.userPath = userPath || resolveUserJournalPath();
  }

  async search(query: string, options: SearchOptions = {}): Promise<SearchResult[]> {
    const {
      limit = 10,
      minScore = 0.1,
      sections,
      dateRange,
      type = 'both'
    } = options;

    // Generate query embedding
    const queryEmbedding = await this.embeddingService.generateEmbedding(query);

    // Collect all embeddings
    const allEmbeddings: Array<EmbeddingData & { type: 'project' | 'user' }> = [];

    if (type === 'both' || type === 'project') {
      const projectEmbeddings = await this.loadEmbeddingsFromPath(this.projectPath, 'project');
      allEmbeddings.push(...projectEmbeddings);
    }

    if (type === 'both' || type === 'user') {
      const userEmbeddings = await this.loadEmbeddingsFromPath(this.userPath, 'user');
      allEmbeddings.push(...userEmbeddings);
    }

    // Filter by criteria
    const filtered = allEmbeddings.filter(embedding => {
      // Filter by sections if specified
      if (sections && sections.length > 0) {
        const hasMatchingSection = sections.some(section => 
          embedding.sections.some(embeddingSection => 
            embeddingSection.toLowerCase().includes(section.toLowerCase())
          )
        );
        if (!hasMatchingSection) return false;
      }

      // Filter by date range
      if (dateRange) {
        const entryDate = new Date(embedding.timestamp);
        if (dateRange.start && entryDate < dateRange.start) return false;
        if (dateRange.end && entryDate > dateRange.end) return false;
      }

      return true;
    });

    // Calculate similarities and sort
    const results: SearchResult[] = filtered
      .map(embedding => {
        const score = this.embeddingService.cosineSimilarity(queryEmbedding, embedding.embedding);
        const excerpt = this.generateExcerpt(embedding.text, query);

        return {
          path: embedding.path,
          score,
          text: embedding.text,
          sections: embedding.sections,
          timestamp: embedding.timestamp,
          excerpt,
          type: embedding.type
        };
      })
      .filter(result => result.score >= minScore)
      .sort((a, b) => b.score - a.score)
      .slice(0, limit);

    return results;
  }

  async listRecent(options: SearchOptions = {}): Promise<SearchResult[]> {
    const {
      limit = 10,
      type = 'both',
      dateRange
    } = options;

    const allEmbeddings: Array<EmbeddingData & { type: 'project' | 'user' }> = [];

    if (type === 'both' || type === 'project') {
      const projectEmbeddings = await this.loadEmbeddingsFromPath(this.projectPath, 'project');
      allEmbeddings.push(...projectEmbeddings);
    }

    if (type === 'both' || type === 'user') {
      const userEmbeddings = await this.loadEmbeddingsFromPath(this.userPath, 'user');
      allEmbeddings.push(...userEmbeddings);
    }

    // Filter by date range
    const filtered = dateRange ? allEmbeddings.filter(embedding => {
      const entryDate = new Date(embedding.timestamp);
      if (dateRange.start && entryDate < dateRange.start) return false;
      if (dateRange.end && entryDate > dateRange.end) return false;
      return true;
    }) : allEmbeddings;

    // Sort by timestamp (most recent first) and limit
    const results: SearchResult[] = filtered
      .sort((a, b) => b.timestamp - a.timestamp)
      .slice(0, limit)
      .map(embedding => ({
        path: embedding.path,
        score: 1, // No similarity score for recent entries
        text: embedding.text,
        sections: embedding.sections,
        timestamp: embedding.timestamp,
        excerpt: this.generateExcerpt(embedding.text, '', 150),
        type: embedding.type
      }));

    return results;
  }

  async readRecentEntries(options: { limit?: number; type?: 'project' | 'user' | 'both' } = {}): Promise<RecentEntryResult[]> {
    const { limit = 5, type = 'both' } = options;

    const recent = await this.listRecent({ limit, type });

    const results: RecentEntryResult[] = [];
    for (const entry of recent) {
      const content = await this.readEntry(entry.path);
      if (content !== null) {
        results.push({
          path: entry.path,
          content,
          sections: entry.sections,
          timestamp: entry.timestamp,
          type: entry.type,
        });
      }
    }

    return results;
  }

  async readEntry(filePath: string): Promise<string | null> {
    const resolvedPath = path.resolve(filePath);

    // Only Markdown entries under the journal directories are readable; reject
    // anything else with a clear error.
    if (path.extname(resolvedPath).toLowerCase() !== '.md') {
      throw new Error(`${resolvedPath} is not a readable journal entry`);
    }
    if (!this.isUnderJournalRoot(resolvedPath, this.journalRoots())) {
      throw new Error(`${resolvedPath} is not a readable journal entry`);
    }

    let realPath: string;
    try {
      realPath = await fs.realpath(resolvedPath);
    } catch (error) {
      if ((error as NodeJS.ErrnoException)?.code === 'ENOENT') {
        return null;
      }
      throw error;
    }

    // Resolve symlinks and confirm the real file is still under a journal
    // directory before reading.
    if (!this.isUnderJournalRoot(realPath, await this.realJournalRoots())) {
      throw new Error(`${resolvedPath} is not a readable journal entry`);
    }

    try {
      return await fs.readFile(realPath, 'utf8');
    } catch (error) {
      if ((error as NodeJS.ErrnoException)?.code === 'ENOENT') {
        return null;
      }
      throw error;
    }
  }

  private journalRoots(): string[] {
    return [this.projectPath, this.userPath].map(root => path.resolve(root));
  }

  private async realJournalRoots(): Promise<string[]> {
    const roots: string[] = [];
    for (const root of this.journalRoots()) {
      try {
        roots.push(await fs.realpath(root));
      } catch {
        // A journal root that doesn't exist on disk can't contain anything.
      }
    }
    return roots;
  }

  private isUnderJournalRoot(candidate: string, roots: string[]): boolean {
    return roots.some(
      root => candidate === root || candidate.startsWith(root + path.sep)
    );
  }

  private async loadEmbeddingsFromPath(
    basePath: string, 
    type: 'project' | 'user'
  ): Promise<Array<EmbeddingData & { type: 'project' | 'user' }>> {
    const embeddings: Array<EmbeddingData & { type: 'project' | 'user' }> = [];

    try {
      const dayDirs = await fs.readdir(basePath);

      for (const dayDir of dayDirs) {
        const dayPath = path.join(basePath, dayDir);
        const stat = await fs.stat(dayPath);

        if (!stat.isDirectory() || !dayDir.match(/^\d{4}-\d{2}-\d{2}$/)) {
          continue;
        }

        const files = await fs.readdir(dayPath);
        const embeddingFiles = files.filter(file => file.endsWith('.embedding'));

        for (const embeddingFile of embeddingFiles) {
          try {
            const embeddingPath = path.join(dayPath, embeddingFile);
            const content = await fs.readFile(embeddingPath, 'utf8');
            const embeddingData = JSON.parse(content);
            embeddings.push({ ...embeddingData, type });
          } catch (error) {
            console.error(`Failed to load embedding ${embeddingFile}:`, error);
            // Continue with other files
          }
        }
      }
    } catch (error) {
      if ((error as NodeJS.ErrnoException)?.code !== 'ENOENT') {
        console.error(`Failed to read embeddings from ${basePath}:`, error);
      }
      // Return empty array if directory doesn't exist
    }

    return embeddings;
  }

  private generateExcerpt(text: string, query: string, maxLength: number = 200): string {
    if (!query || query.trim() === '') {
      return text.slice(0, maxLength) + (text.length > maxLength ? '...' : '');
    }

    const queryWords = query.toLowerCase().split(/\s+/);
    const textLower = text.toLowerCase();

    // Find the best position to start the excerpt
    let bestPosition = 0;
    let bestScore = 0;

    for (let i = 0; i <= text.length - maxLength; i += 20) {
      const window = textLower.slice(i, i + maxLength);
      const score = queryWords.reduce((sum, word) => {
        return sum + (window.includes(word) ? 1 : 0);
      }, 0);

      if (score > bestScore) {
        bestScore = score;
        bestPosition = i;
      }
    }

    let excerpt = text.slice(bestPosition, bestPosition + maxLength);
    if (bestPosition > 0) excerpt = '...' + excerpt;
    if (bestPosition + maxLength < text.length) excerpt += '...';

    return excerpt;
  }
}

// ABOUTME: Unit tests for path resolution utilities
// ABOUTME: Tests cross-platform fallback logic and environment handling

import * as path from 'path';
import { resolveJournalPath, resolveUserJournalPath, resolveProjectJournalPath } from '../src/paths';

describe('Path resolution utilities', () => {
  let originalEnv: NodeJS.ProcessEnv;

  beforeEach(() => {
    originalEnv = { ...process.env };
  });

  afterEach(() => {
    process.env = originalEnv;
  });

  test('resolveJournalPath uses current directory when reasonable', () => {
    // Mock a reasonable current working directory
    const mockCwd = '/Users/test/projects/my-app';
    jest.spyOn(process, 'cwd').mockReturnValue(mockCwd);

    const result = resolveJournalPath('.private-journal', true);
    expect(result).toBe(path.join(mockCwd, '.private-journal'));
  });

  test('resolveJournalPath skips system directories', () => {
    const systemPaths = ['/', 'C:\\', '/System', '/usr'];

    systemPaths.forEach(systemPath => {
      jest.spyOn(process, 'cwd').mockReturnValue(systemPath);
      process.env.HOME = '/Users/test';

      const result = resolveJournalPath('.private-journal', true);
      expect(result).toBe('/Users/test/.private-journal');
    });
  });

  test('resolveJournalPath falls back to HOME when current directory excluded', () => {
    process.env.HOME = '/Users/test';
    delete process.env.USERPROFILE;

    const result = resolveJournalPath('.private-journal', false);
    expect(result).toBe('/Users/test/.private-journal');
  });

  test('resolveJournalPath uses USERPROFILE on Windows', () => {
    delete process.env.HOME;
    process.env.USERPROFILE = 'C:\\Users\\test';

    const result = resolveJournalPath('.private-journal', false);
    expect(result).toBe(path.join('C:\\Users\\test', '.private-journal'));
  });

  test('resolveJournalPath falls back to temp directory', () => {
    delete process.env.HOME;
    delete process.env.USERPROFILE;
    delete process.env.TEMP;
    delete process.env.TMP;

    const result = resolveJournalPath('.private-journal', false);
    expect(result).toBe('/tmp/.private-journal');
  });

  test('resolveUserJournalPath excludes current directory', () => {
    const mockCwd = '/Users/test/projects/my-app';
    jest.spyOn(process, 'cwd').mockReturnValue(mockCwd);
    process.env.HOME = '/Users/test';

    const result = resolveUserJournalPath();
    expect(result).toBe('/Users/test/.private-journal');
    expect(result).not.toContain('projects/my-app');
  });

  test('resolveProjectJournalPath includes current directory', () => {
    const mockCwd = '/Users/test/projects/my-app';
    jest.spyOn(process, 'cwd').mockReturnValue(mockCwd);

    const result = resolveProjectJournalPath();
    expect(result).toBe(path.join(mockCwd, '.private-journal'));
  });

  test('both user and project paths are consistent when no project context', () => {
    // Simulate no reasonable project directory
    jest.spyOn(process, 'cwd').mockReturnValue('/');
    process.env.HOME = '/Users/test';

    const userPath = resolveUserJournalPath();
    const projectPath = resolveProjectJournalPath();

    expect(userPath).toBe('/Users/test/.private-journal');
    expect(projectPath).toBe('/Users/test/.private-journal');
  });

  describe('PRIVATE_JOURNAL_PATH override', () => {
    test('resolveJournalPath uses PRIVATE_JOURNAL_PATH when set', () => {
      process.env.PRIVATE_JOURNAL_PATH = '/data/journals';
      process.env.HOME = '/Users/test';
      jest.spyOn(process, 'cwd').mockReturnValue('/Users/test/projects/my-app');

      const result = resolveJournalPath('.private-journal', true);
      expect(result).toBe('/data/journals');
    });

    test('resolveUserJournalPath uses PRIVATE_JOURNAL_PATH when set', () => {
      process.env.PRIVATE_JOURNAL_PATH = '/data/journals';
      process.env.HOME = '/Users/test';

      const result = resolveUserJournalPath();
      expect(result).toBe('/data/journals');
    });

    test('resolveProjectJournalPath uses PRIVATE_JOURNAL_PATH when set', () => {
      process.env.PRIVATE_JOURNAL_PATH = '/data/journals';
      jest.spyOn(process, 'cwd').mockReturnValue('/Users/test/projects/my-app');

      const result = resolveProjectJournalPath();
      expect(result).toBe('/data/journals');
    });

    test('PRIVATE_JOURNAL_PATH makes user and project paths identical', () => {
      process.env.PRIVATE_JOURNAL_PATH = '/container/journal-data';
      process.env.HOME = '/Users/test';
      jest.spyOn(process, 'cwd').mockReturnValue('/Users/test/projects/my-app');

      const userPath = resolveUserJournalPath();
      const projectPath = resolveProjectJournalPath();

      expect(userPath).toBe('/container/journal-data');
      expect(projectPath).toBe('/container/journal-data');
    });

    test('PRIVATE_JOURNAL_PATH ignores subdirectory parameter', () => {
      process.env.PRIVATE_JOURNAL_PATH = '/data/journals';

      const result = resolveJournalPath('.some-other-name', true);
      expect(result).toBe('/data/journals');
    });
  });
});

// ABOUTME: Unit tests for journal writing functionality
// ABOUTME: Tests file system operations, timestamps, and formatting


import * as fs from 'fs/promises';
import * as path from 'path';
import * as os from 'os';
import { JournalManager } from '../src/journal';

function getFormattedDate(date: Date): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

describe('JournalManager', () => {
  let projectTempDir: string;
  let userTempDir: string;
  let journalManager: JournalManager;
  let originalHome: string | undefined;

  beforeEach(async () => {
    projectTempDir = await fs.mkdtemp(path.join(os.tmpdir(), 'journal-project-test-'));
    userTempDir = await fs.mkdtemp(path.join(os.tmpdir(), 'journal-user-test-'));

    // Mock HOME environment
    originalHome = process.env.HOME;
    process.env.HOME = userTempDir;

    journalManager = new JournalManager(projectTempDir);
  });

  afterEach(async () => {
    // Restore original HOME
    if (originalHome !== undefined) {
      process.env.HOME = originalHome;
    } else {
      delete process.env.HOME;
    }

    await fs.rm(projectTempDir, { recursive: true, force: true });
    await fs.rm(userTempDir, { recursive: true, force: true });
  });

  test('writes project notes to project directory', async () => {
    const thoughts = {
      project_notes: 'The architecture is solid'
    };

    await journalManager.writeThoughts(thoughts);

    const today = new Date();
    const dateString = getFormattedDate(today);
    const projectDayDir = path.join(projectTempDir, dateString);

    const projectFiles = await fs.readdir(projectDayDir);
    expect(projectFiles).toHaveLength(2); // .md and .embedding

    const projectMdFile = projectFiles.find(f => f.endsWith('.md'))!;
    const projectContent = await fs.readFile(path.join(projectDayDir, projectMdFile), 'utf8');

    expect(projectContent).toContain('## Project Notes');
    expect(projectContent).toContain('The architecture is solid');
    expect(projectContent).not.toContain('## Reflections');
  });

  test('writeThoughts produces filenames with microsecond precision', async () => {
    await journalManager.writeThoughts({
      reflections: 'Filename format check'
    });

    const today = new Date();
    const dateString = getFormattedDate(today);
    const userDayDir = path.join(userTempDir, '.private-journal', dateString);
    const userFiles = await fs.readdir(userDayDir);

    const mdFile = userFiles.find(f => f.endsWith('.md'));
    expect(mdFile).toBeDefined();
    expect(mdFile).toMatch(/^\d{2}-\d{2}-\d{2}-\d{6}\.md$/);
  });

  test('writeThoughts emits well-formed YAML frontmatter', async () => {
    await journalManager.writeThoughts({
      reflections: 'Frontmatter shape check'
    });

    const today = new Date();
    const dateString = getFormattedDate(today);
    const userDayDir = path.join(userTempDir, '.private-journal', dateString);
    const userFiles = await fs.readdir(userDayDir);
    const mdFile = userFiles.find(f => f.endsWith('.md'))!;
    const fileContent = await fs.readFile(path.join(userDayDir, mdFile), 'utf8');

    const lines = fileContent.split('\n');
    expect(lines[0]).toBe('---');
    expect(lines[1]).toMatch(/^title: ".*"$/);
    expect(lines[2]).toMatch(/^date: \d{4}-\d{2}-\d{2}T/);
    expect(lines[3]).toMatch(/^timestamp: \d+$/);
    expect(lines[4]).toBe('---');
  });

  test('writeThoughts produces distinct filenames for rapid successive writes', async () => {
    await journalManager.writeThoughts({ reflections: 'First rapid entry' });
    await journalManager.writeThoughts({ reflections: 'Second rapid entry' });

    const today = new Date();
    const dateString = getFormattedDate(today);
    const userDayDir = path.join(userTempDir, '.private-journal', dateString);
    const userFiles = await fs.readdir(userDayDir);

    const mdFiles = userFiles.filter(f => f.endsWith('.md'));
    expect(mdFiles).toHaveLength(2);
    expect(mdFiles[0]).not.toEqual(mdFiles[1]);
  });

  test('writes user thoughts to user directory', async () => {
    const thoughts = {
      reflections: 'I feel great about this feature',
      technical_insights: 'TypeScript interfaces are powerful'
    };

    await journalManager.writeThoughts(thoughts);

    const today = new Date();
    const dateString = getFormattedDate(today);
    const userDayDir = path.join(userTempDir, '.private-journal', dateString);

    const userFiles = await fs.readdir(userDayDir);
    expect(userFiles).toHaveLength(2); // .md and .embedding

    const userMdFile = userFiles.find(f => f.endsWith('.md'))!;
    const userContent = await fs.readFile(path.join(userDayDir, userMdFile), 'utf8');

    expect(userContent).toContain('## Reflections');
    expect(userContent).toContain('I feel great about this feature');
    expect(userContent).toContain('## Technical Insights');
    expect(userContent).toContain('TypeScript interfaces are powerful');
    expect(userContent).not.toContain('## Project Notes');
  });

  test('writes observations to user directory', async () => {
    const thoughts = {
      observations: 'I noticed the test runner caches pycache weirdly'
    };

    await journalManager.writeThoughts(thoughts);

    const today = new Date();
    const dateString = getFormattedDate(today);
    const userDayDir = path.join(userTempDir, '.private-journal', dateString);

    const userFiles = await fs.readdir(userDayDir);
    expect(userFiles).toHaveLength(2); // .md and .embedding

    const userMdFile = userFiles.find(f => f.endsWith('.md'))!;
    const userContent = await fs.readFile(path.join(userDayDir, userMdFile), 'utf8');

    expect(userContent).toContain('## Observations');
    expect(userContent).toContain('I noticed the test runner caches pycache weirdly');
    expect(userContent).not.toContain('## Project Notes');
  });

  test('splits thoughts between project and user directories', async () => {
    const thoughts = {
      reflections: 'I feel great',
      project_notes: 'The architecture is solid',
      user_context: 'Jesse prefers simple solutions',
      technical_insights: 'TypeScript is powerful',
      world_knowledge: 'Git workflows matter'
    };

    await journalManager.writeThoughts(thoughts);

    const today = new Date();
    const dateString = getFormattedDate(today);

    // Check project directory
    const projectDayDir = path.join(projectTempDir, dateString);
    const projectFiles = await fs.readdir(projectDayDir);
    expect(projectFiles).toHaveLength(2); // .md and .embedding

    const projectMdFile = projectFiles.find(f => f.endsWith('.md'))!;
    const projectContent = await fs.readFile(path.join(projectDayDir, projectMdFile), 'utf8');
    expect(projectContent).toContain('## Project Notes');
    expect(projectContent).toContain('The architecture is solid');
    expect(projectContent).not.toContain('## Reflections');

    // Check user directory
    const userDayDir = path.join(userTempDir, '.private-journal', dateString);
    const userFiles = await fs.readdir(userDayDir);
    expect(userFiles).toHaveLength(2); // .md and .embedding

    const userMdFile = userFiles.find(f => f.endsWith('.md'))!;
    const userContent = await fs.readFile(path.join(userDayDir, userMdFile), 'utf8');
    expect(userContent).toContain('## Reflections');
    expect(userContent).toContain('## User Context');
    expect(userContent).toContain('## Technical Insights');
    expect(userContent).toContain('## World Knowledge');
    expect(userContent).not.toContain('## Project Notes');
  });

  test('handles thoughts with only user sections', async () => {
    const thoughts = {
      world_knowledge: 'Learned something interesting about databases'
    };

    await journalManager.writeThoughts(thoughts);

    const today = new Date();
    const dateString = getFormattedDate(today);

    // Should only create user directory, not project directory
    const userDayDir = path.join(userTempDir, '.private-journal', dateString);
    const userFiles = await fs.readdir(userDayDir);
    expect(userFiles).toHaveLength(2); // .md and .embedding

    const userMdFile = userFiles.find(f => f.endsWith('.md'))!;
    const userContent = await fs.readFile(path.join(userDayDir, userMdFile), 'utf8');
    expect(userContent).toContain('## World Knowledge');
    expect(userContent).toContain('Learned something interesting about databases');

    // Project directory should not exist
    const projectDayDir = path.join(projectTempDir, dateString);
    await expect(fs.access(projectDayDir)).rejects.toThrow();
  });

  test('handles thoughts with only project sections', async () => {
    const thoughts = {
      project_notes: 'This specific codebase pattern works well'
    };

    await journalManager.writeThoughts(thoughts);

    const today = new Date();
    const dateString = getFormattedDate(today);

    // Should only create project directory, not user directory
    const projectDayDir = path.join(projectTempDir, dateString);
    const projectFiles = await fs.readdir(projectDayDir);
    expect(projectFiles).toHaveLength(2); // .md and .embedding

    const projectMdFile = projectFiles.find(f => f.endsWith('.md'))!;
    const projectContent = await fs.readFile(path.join(projectDayDir, projectMdFile), 'utf8');
    expect(projectContent).toContain('## Project Notes');
    expect(projectContent).toContain('This specific codebase pattern works well');

    // User directory should not exist
    const userDayDir = path.join(userTempDir, '.private-journal', dateString);
    await expect(fs.access(userDayDir)).rejects.toThrow();
  });

  test('uses explicit user journal path when provided', async () => {
    const customUserDir = await fs.mkdtemp(path.join(os.tmpdir(), 'custom-user-'));
    const customJournalManager = new JournalManager(projectTempDir, customUserDir);

    try {
      const thoughts = { reflections: 'Testing custom path' };
      await customJournalManager.writeThoughts(thoughts);

      const today = new Date();
      const dateString = getFormattedDate(today);
      const customDayDir = path.join(customUserDir, dateString);

      const customFiles = await fs.readdir(customDayDir);
      expect(customFiles).toHaveLength(2); // .md and .embedding

      const customMdFile = customFiles.find(f => f.endsWith('.md'))!;
      const customContent = await fs.readFile(path.join(customDayDir, customMdFile), 'utf8');
      expect(customContent).toContain('Testing custom path');
    } finally {
      await fs.rm(customUserDir, { recursive: true, force: true });
    }
  });
});

// ABOUTME: Unit tests for embedding functionality and search capabilities
// ABOUTME: Tests embedding generation, storage, and semantic search operations

import * as fs from 'fs/promises';
import * as path from 'path';
import * as os from 'os';

import { EmbeddingService } from '../src/embeddings';
import { SearchService } from '../src/search';
import { JournalManager } from '../src/journal';

describe('Embedding and Search functionality', () => {
  let projectTempDir: string;
  let userTempDir: string;
  let journalManager: JournalManager;
