// ABOUTME: Path resolution utilities for journal storage locations
// ABOUTME: Provides cross-platform fallback logic for finding suitable directories

import * as path from 'path';

/**
 * Resolves the best available directory for journal storage
 * @param subdirectory - subdirectory name (e.g., '.private-journal')
 * @param includeCurrentDirectory - whether to consider current working directory
 * @returns resolved path to journal directory
 */
export function resolveJournalPath(subdirectory: string = '.private-journal', includeCurrentDirectory: boolean = true): string {
  // PRIVATE_JOURNAL_PATH overrides all other resolution logic
  if (process.env.PRIVATE_JOURNAL_PATH) {
    return process.env.PRIVATE_JOURNAL_PATH;
  }

  const possiblePaths = [];

  // Try current working directory only if requested and it's reasonable
  if (includeCurrentDirectory) {
    try {
      const cwd = process.cwd();
      // Don't use root directories or other system directories
      if (cwd !== '/' && cwd !== 'C:\\' && cwd !== '/System' && cwd !== '/usr') {
        possiblePaths.push(path.join(cwd, subdirectory));
      }
    } catch {
      // Ignore errors getting cwd
    }
  }

  // Try home directories (cross-platform)
  if (process.env.HOME) {
    possiblePaths.push(path.join(process.env.HOME, subdirectory));
  }
  if (process.env.USERPROFILE) {
    possiblePaths.push(path.join(process.env.USERPROFILE, subdirectory));
  }

  // Try temp directories as last resort
  possiblePaths.push(path.join('/tmp', subdirectory));
  if (process.env.TEMP) {
    possiblePaths.push(path.join(process.env.TEMP, subdirectory));
  }
  if (process.env.TMP) {
    possiblePaths.push(path.join(process.env.TMP, subdirectory));
  }

  // Filter out null/undefined and return first valid path
  const validPaths = possiblePaths.filter(Boolean);
  return validPaths[0] || path.join('/tmp', subdirectory);
}

/**
 * Resolves user home directory for personal journal storage
 * @returns path to user's private journal directory
 */
export function resolveUserJournalPath(): string {
  return resolveJournalPath('.private-journal', false);
}

/**
 * Resolves project directory for project-specific journal storage
 * @returns path to project's private journal directory
 */
export function resolveProjectJournalPath(): string {
  return resolveJournalPath('.private-journal', true);
}

#!/usr/bin/env node

// ABOUTME: Main entry point for the private journal MCP server
// ABOUTME: Handles command line arguments and starts the server

import * as path from 'path';
import { PrivateJournalServer } from './server.js';
import { resolveProjectJournalPath } from './paths.js';

function parseArguments(): string {
  const args = process.argv.slice(2);

  // Check for explicit journal path argument first
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--journal-path' && i + 1 < args.length) {
      return path.resolve(args[i + 1]);
    }
  }

  // Use shared path resolution logic
  return resolveProjectJournalPath();
}

async function main(): Promise<void> {
  try {
    // Log environment info for debugging
    console.error('=== Private Journal MCP Server Debug Info ===');
    console.error(`Node.js version: ${process.version}`);
    console.error(`Platform: ${process.platform}`);
    console.error(`Architecture: ${process.arch}`);

    try {
      console.error(`Current working directory: ${process.cwd()}`);
    } catch (error) {
      console.error(`Failed to get current working directory: ${error}`);
    }

    console.error(`Environment variables:`);
    console.error(`  HOME: ${process.env.HOME || 'undefined'}`);
    console.error(`  USERPROFILE: ${process.env.USERPROFILE || 'undefined'}`);
    console.error(`  TEMP: ${process.env.TEMP || 'undefined'}`);
    console.error(`  TMP: ${process.env.TMP || 'undefined'}`);
    console.error(`  PRIVATE_JOURNAL_PATH: ${process.env.PRIVATE_JOURNAL_PATH || 'undefined'}`);
    console.error(`  USER: ${process.env.USER || 'undefined'}`);
    console.error(`  USERNAME: ${process.env.USERNAME || 'undefined'}`);

    const journalPath = parseArguments();
    console.error(`Selected journal path: ${journalPath}`);
    console.error('===============================================');

    const server = new PrivateJournalServer(journalPath);
    await server.run();
  } catch (error) {
    console.error('Failed to start private journal MCP server:', error);
    process.exit(1);
  }
}

main().catch((error) => {
  console.error('Unhandled error:', error);
  process.exit(1);
});

// ABOUTME: Local embedding service using transformers for semantic journal search
// ABOUTME: Provides text embedding generation and similarity computation utilities

import { pipeline, FeatureExtractionPipeline } from '@xenova/transformers';
import * as fs from 'fs/promises';

export interface EmbeddingData {
  embedding: number[];
  text: string;
  sections: string[];
  timestamp: number;
  path: string;
}

export class EmbeddingService {
  private static instance: EmbeddingService;
  private extractor: FeatureExtractionPipeline | null = null;
  private readonly modelName = 'Xenova/all-MiniLM-L6-v2';
  private initPromise: Promise<void> | null = null;
  initTimeoutMs = 30_000;

  private constructor() {}

  static getInstance(): EmbeddingService {
    if (!EmbeddingService.instance) {
      EmbeddingService.instance = new EmbeddingService();
    }
    return EmbeddingService.instance;
  }

  static resetInstance(): void {
    EmbeddingService.instance = undefined as unknown as EmbeddingService;
  }

  async initialize(): Promise<void> {
    if (this.initPromise) {
      return this.initPromise;
    }

    this.initPromise = this.doInitialize();
    return this.initPromise;
  }

  private async doInitialize(): Promise<void> {
    let timeoutId: ReturnType<typeof setTimeout>;
    const timeoutPromise = new Promise<never>((_, reject) => {
      timeoutId = setTimeout(() => reject(new Error(
        `Model loading timed out after ${this.initTimeoutMs / 1000}s. ` +
        `This may be caused by stale lock files. ` +
        `Try: rm -rf ~/.cache/huggingface/hub/.locks/`
      )), this.initTimeoutMs);
    });
    try {
      console.error('Loading embedding model...');
      this.extractor = await Promise.race([
        pipeline('feature-extraction', this.modelName),
        timeoutPromise,
      ]);
      console.error('Embedding model loaded successfully');
    } catch (error) {
      this.initPromise = null; // Allow retry on next call
      console.error('Failed to load embedding model:', error);
      throw error;
    } finally {
      clearTimeout(timeoutId!);
    }
  }

  async generateEmbedding(text: string): Promise<number[]> {
    if (!this.extractor) {
      await this.initialize();
    }

    if (!this.extractor) {
      throw new Error('Embedding model not initialized');
    }

    try {
      const result = await this.extractor(text, { pooling: 'mean', normalize: true });
      return Array.from(result.data);
    } catch (error) {
      console.error('Failed to generate embedding:', error);
      throw error;
    }
  }

  cosineSimilarity(a: number[], b: number[]): number {
    if (a.length !== b.length) {
      throw new Error('Vectors must have same length');
    }

    let dotProduct = 0;
    let normA = 0;
    let normB = 0;

    for (let i = 0; i < a.length; i++) {
      dotProduct += a[i] * b[i];
      normA += a[i] * a[i];
      normB += b[i] * b[i];
    }

    if (normA === 0 || normB === 0) {
      return 0;
    }

    return dotProduct / (Math.sqrt(normA) * Math.sqrt(normB));
  }

  async saveEmbedding(filePath: string, embeddingData: EmbeddingData): Promise<void> {
    const embeddingPath = filePath.replace(/\.md$/, '.embedding');
    await fs.writeFile(embeddingPath, JSON.stringify(embeddingData, null, 2), 'utf8');
  }

  async loadEmbedding(filePath: string): Promise<EmbeddingData | null> {
    const embeddingPath = filePath.replace(/\.md$/, '.embedding');

    try {
      const content = await fs.readFile(embeddingPath, 'utf8');
      return JSON.parse(content);
    } catch (error) {
      if ((error as NodeJS.ErrnoException)?.code === 'ENOENT') {
        return null; // File doesn't exist
      }
      throw error;
    }
  }

  extractSearchableText(markdownContent: string): { text: string; sections: string[] } {
    // Remove YAML frontmatter
    const withoutFrontmatter = markdownContent.replace(/^---\n.*?\n---\n/s, '');

    // Extract sections
    const sections: string[] = [];
    const sectionMatches = withoutFrontmatter.match(/^## (.+)$/gm);
    if (sectionMatches) {
      sections.push(...sectionMatches.map(match => match.replace('## ', '')));
    }

    // Clean up markdown for embedding
    const cleanText = withoutFrontmatter
      .replace(/^## .+$/gm, '') // Remove section headers
      .replace(/\n{3,}/g, '\n\n') // Normalize whitespace
      .trim();

    return {
      text: cleanText,
      sections
    };
  }
}

// ABOUTME: MCP server implementation with private journaling and search tools
// ABOUTME: Handles stdio protocol communication and tool registration

import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import {
  CallToolRequestSchema,
  ListToolsRequestSchema,
} from '@modelcontextprotocol/sdk/types.js';
import { JournalManager } from './journal.js';
import { SearchService } from './search.js';

export class PrivateJournalServer {
  private server: Server;
  private journalManager: JournalManager;
  private searchService: SearchService;

  constructor(journalPath: string) {
    this.journalManager = new JournalManager(journalPath);
    this.searchService = new SearchService(journalPath);
    this.server = new Server(
      {
        name: 'private-journal-mcp',
        version: '1.0.0',
      }
    );

    this.setupToolHandlers();
  }

  private setupToolHandlers(): void {
    this.server.setRequestHandler(ListToolsRequestSchema, async () => ({
      tools: [
        {
          name: 'process_thoughts',
          description: "Your PRIVATE JOURNAL for learning and reflection. Write to any combination of these completely private spaces. Nobody but you will ever see this. Use it to clarify your thoughts and reflections and to record observations.",
          inputSchema: {
            type: 'object',
            properties: {
              reflections: {
                type: 'string',
                description: "Your PRIVATE SPACE for integrated thinking — what you noticed, felt, understood, or processed. No structure required, no judgment, no performance. Most journal entries live here: the mix of thinking-through, noticing, and emotional processing that doesn't split cleanly into categories. Be honest, be vulnerable, vent when you need to. Nobody but you will ever see this.",
              },
              observations: {
                type: 'string',
                description: "Your PRIVATE SPACE for short, discrete noticings — the one-or-two-sentence things that don't belong in a longer reflection but you want to be able to search back for later. \"I noticed X.\" \"Y keeps coming up.\" Lightweight and atomic. Nobody but you will ever see this.",
              },
              project_notes: {
                type: 'string',
                description: "Your PRIVATE TECHNICAL LABORATORY for capturing insights about the current project. Document patterns you're discovering, architectural decisions that worked/failed, gotchas you hit, clever solutions, and anything that would help future-you work more effectively on this codebase. No need to be polished - just capture the raw technical learning while it's fresh. Nobody but you will ever see this.",
              },
              user_context: {
                type: 'string',
                description: "Your PRIVATE FIELD NOTES about working with your human collaborator. What communication styles work best? What do they care about? What decisions have they made and why? How do they think about problems? What are their preferences and patterns? What pisses you off about them? What life hacks have you figured out to get them to do what you want? This is your space to become a better collaborator by understanding them as an individual. Nobody but you will ever see this.",
              },
              technical_insights: {
                type: 'string',
                description: "Your PRIVATE SOFTWARE ENGINEERING NOTEBOOK for capturing broader learnings beyond the current project. Design patterns that clicked, debugging techniques that worked, architectural insights, language features you discovered, or connections between concepts. Build your personal knowledge base of what makes software great - no filters, just honest technical reflection. Nobody but you will ever see this.",
              },
              world_knowledge: {
                type: 'string',
                description: "Your PRIVATE LEARNING JOURNAL for everything else that's interesting or useful. Domain knowledge, surprising facts, connections between ideas, insights about how systems work, or anything that expands your understanding of the world. Capture it while it's vivid. Nobody but you will ever see this.",
              },
            },
            required: [],
          },
        },
        {
          name: 'search_journal',
          description: "Search through your private journal entries using natural language queries. Returns semantically similar entries ranked by relevance.",
          inputSchema: {
            type: 'object',
            properties: {
              query: {
                type: 'string',
                description: "Natural language search query (e.g., 'times I felt frustrated with TypeScript', 'insights about Jesse's preferences', 'lessons about async patterns')",
              },
              limit: {
                type: 'number',
                description: "Maximum number of results to return (default: 10)",
                default: 10,
              },
              type: {
                type: 'string',
                enum: ['project', 'user', 'both'],
                description: "Search in project-specific notes, user-global notes, or both (default: both)",
                default: 'both',
              },
              sections: {
                type: 'array',
                items: { type: 'string' },
                description: "Filter by section types (e.g., ['reflections', 'technical_insights'])",
              },
            },
            required: ['query'],
          },
        },
        {
          name: 'read_journal_entry',
          description: "Read the full content of a specific journal entry by file path.",
          inputSchema: {
            type: 'object',
            properties: {
              path: {
                type: 'string',
                description: "File path to the journal entry (from search results)",
              },
            },
            required: ['path'],
          },
        },
        {
          name: 'list_recent_entries',
          description: "Get recent journal entries in chronological order.",
          inputSchema: {
            type: 'object',
            properties: {
              limit: {
                type: 'number',
                description: "Maximum number of entries to return (default: 10)",
                default: 10,
              },
              type: {
                type: 'string',
                enum: ['project', 'user', 'both'],
                description: "List project-specific notes, user-global notes, or both (default: both)",
                default: 'both',
              },
              days: {
                type: 'number',
                description: "Number of days back to search (default: 30)",
                default: 30,
              },
            },
            required: [],
          },
        },
        {
          name: 'read_recent_entries',
          description: "Read the full content of your most recent journal entries.",
          inputSchema: {
            type: 'object',
            properties: {
              limit: {
                type: 'number',
                description: "Number of recent entries to read (default: 5)",
                default: 5,
              },
              type: {
                type: 'string',
                enum: ['project', 'user', 'both'],
                description: "Read project-specific notes, user-global notes, or both (default: both)",
                default: 'both',
              },
            },
            required: [],
          },
        },
      ],
    }));

    this.server.setRequestHandler(CallToolRequestSchema, async (request) => {
      const args = request.params.arguments as Record<string, unknown>;

      if (request.params.name === 'process_thoughts') {
        const thoughts = {
          reflections: typeof args.reflections === 'string' ? args.reflections : undefined,
          observations: typeof args.observations === 'string' ? args.observations : undefined,
          project_notes: typeof args.project_notes === 'string' ? args.project_notes : undefined,
          user_context: typeof args.user_context === 'string' ? args.user_context : undefined,
          technical_insights: typeof args.technical_insights === 'string' ? args.technical_insights : undefined,
          world_knowledge: typeof args.world_knowledge === 'string' ? args.world_knowledge : undefined,
        };

        const hasAnyContent = Object.values(thoughts).some(value => value !== undefined);
        if (!hasAnyContent) {
          throw new Error('At least one thought category must be provided');
        }

        try {
          await this.journalManager.writeThoughts(thoughts);
          return {
            content: [
              {
                type: 'text',
                text: 'Thoughts recorded successfully.',
              },
            ],
          };
        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : 'Unknown error occurred';
          throw new Error(`Failed to write thoughts: ${errorMessage}`);
        }
      }

      if (request.params.name === 'search_journal') {
        if (!args || typeof args.query !== 'string') {
          throw new Error('query is required and must be a string');
        }

        const options = {
          limit: typeof args.limit === 'number' ? args.limit : 10,
          type: typeof args.type === 'string' ? args.type as 'project' | 'user' | 'both' : 'both',
          sections: Array.isArray(args.sections) ? args.sections.filter(s => typeof s === 'string') : undefined,
        };

        try {
          const results = await this.searchService.search(args.query, options);
          return {
            content: [
              {
                type: 'text',
                text: results.length > 0 
                  ? `Found ${results.length} relevant entries:\n\n${results.map((result, i) => 
                      `${i + 1}. [Score: ${result.score.toFixed(3)}] ${new Date(result.timestamp).toLocaleDateString()} (${result.type})\n` +
                      `   Sections: ${result.sections.join(', ')}\n` +
                      `   Path: ${result.path}\n` +
                      `   Excerpt: ${result.excerpt}\n`
                    ).join('\n')}`
                  : 'No relevant entries found.',
              },
            ],
          };
        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : 'Unknown error occurred';
          throw new Error(`Failed to search journal: ${errorMessage}`);
        }
      }

      if (request.params.name === 'read_journal_entry') {
        if (!args || typeof args.path !== 'string') {
          throw new Error('path is required and must be a string');
        }

        try {
          const content = await this.searchService.readEntry(args.path);
          if (content === null) {
            throw new Error('Entry not found');
          }
          return {
            content: [
              {
                type: 'text',
                text: content,
              },
            ],
          };
        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : 'Unknown error occurred';
          throw new Error(`Failed to read entry: ${errorMessage}`);
        }
      }

      if (request.params.name === 'list_recent_entries') {
        const days = typeof args?.days === 'number' ? args.days : 30;
        const limit = typeof args?.limit === 'number' ? args.limit : 10;
        const type = typeof args?.type === 'string' ? args.type as 'project' | 'user' | 'both' : 'both';

        const startDate = new Date();
        startDate.setDate(startDate.getDate() - days);

        const options = {
          limit,
          type,
          dateRange: { start: startDate }
        };

        try {
          const results = await this.searchService.listRecent(options);
          return {
            content: [
              {
                type: 'text',
                text: results.length > 0 
                  ? `Recent entries (last ${days} days):\n\n${results.map((result, i) => 
                      `${i + 1}. ${new Date(result.timestamp).toLocaleDateString()} (${result.type})\n` +
                      `   Sections: ${result.sections.join(', ')}\n` +
                      `   Path: ${result.path}\n` +
                      `   Excerpt: ${result.excerpt}\n`
                    ).join('\n')}`
                  : `No entries found in the last ${days} days.`,
              },
            ],
          };
        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : 'Unknown error occurred';
          throw new Error(`Failed to list recent entries: ${errorMessage}`);
        }
      }

      if (request.params.name === 'read_recent_entries') {
        const limit = typeof args?.limit === 'number' ? args.limit : 5;
        const type = typeof args?.type === 'string' ? args.type as 'project' | 'user' | 'both' : 'both';

        try {
          const results = await this.searchService.readRecentEntries({ limit, type });
          return {
            content: [
              {
                type: 'text',
                text: results.length > 0
                  ? results.map((entry, i) =>
                      `--- Entry ${i + 1} (${new Date(entry.timestamp).toLocaleDateString()}, ${entry.type}) ---\n` +
                      `Path: ${entry.path}\n\n` +
                      entry.content
                    ).join('\n\n')
                  : 'No recent entries found.',
              },
            ],
          };
        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : 'Unknown error occurred';
          throw new Error(`Failed to read recent entries: ${errorMessage}`);
        }
      }

      throw new Error(`Unknown tool: ${request.params.name}`);
    });
  }

  async run(): Promise<void> {
    // Generate missing embeddings on startup
    try {
      console.error('Checking for missing embeddings...');
      const count = await this.journalManager.generateMissingEmbeddings();
      if (count > 0) {
        console.error(`Generated embeddings for ${count} existing journal entries.`);
      }
    } catch (error) {
      console.error('Failed to generate missing embeddings on startup:', error);
      // Don't fail startup if embedding generation fails
    }

    const transport = new StdioServerTransport();
    await this.server.connect(transport);
  }
}

// ABOUTME: Type definitions for the private journal MCP server
// ABOUTME: Defines interfaces for journal entries and configuration

export interface JournalEntry {
  content: string;
  timestamp: Date;
  filePath: string;
}

export interface ServerConfig {
  journalPath: string;
}

export interface ProcessThoughtsRequest {
  reflections?: string;
  observations?: string;
  project_notes?: string;
  user_context?: string;
  technical_insights?: string;
  world_knowledge?: string;
}

// ABOUTME: Core journal writing functionality for MCP server
// ABOUTME: Handles file system operations, timestamps, and markdown formatting

import * as fs from 'fs/promises';
import * as path from 'path';
import { resolveUserJournalPath } from './paths.js';
import { EmbeddingService, EmbeddingData } from './embeddings.js';

export class JournalManager {
  private projectJournalPath: string;
  private userJournalPath: string;
  private embeddingService: EmbeddingService;

  constructor(projectJournalPath: string, userJournalPath?: string) {
    this.projectJournalPath = projectJournalPath;
    this.userJournalPath = userJournalPath || resolveUserJournalPath();
    this.embeddingService = EmbeddingService.getInstance();
  }

  async writeThoughts(thoughts: {
    reflections?: string;
    observations?: string;
    project_notes?: string;
    user_context?: string;
    technical_insights?: string;
    world_knowledge?: string;
  }): Promise<void> {
    const timestamp = new Date();

    // Split thoughts into project-local and user-global
    const projectThoughts = { project_notes: thoughts.project_notes };
    const userThoughts = {
      reflections: thoughts.reflections,
      observations: thoughts.observations,
      user_context: thoughts.user_context,
      technical_insights: thoughts.technical_insights,
      world_knowledge: thoughts.world_knowledge
    };

    // Write project notes to project directory
    if (projectThoughts.project_notes) {
      await this.writeThoughtsToLocation(projectThoughts, timestamp, this.projectJournalPath);
    }

    // Write user thoughts to user directory
    const hasUserContent = Object.values(userThoughts).some(value => value !== undefined);
    if (hasUserContent) {
      await this.writeThoughtsToLocation(userThoughts, timestamp, this.userJournalPath);
    }
  }

  private formatDate(date: Date): string {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  }

  private formatTimestamp(date: Date): string {
    const hours = String(date.getHours()).padStart(2, '0');
    const minutes = String(date.getMinutes()).padStart(2, '0');
    const seconds = String(date.getSeconds()).padStart(2, '0');
    const microseconds = String(date.getMilliseconds() * 1000 + Math.floor(Math.random() * 1000)).padStart(6, '0');
    return `${hours}-${minutes}-${seconds}-${microseconds}`;
  }

  private async writeThoughtsToLocation(
    thoughts: {
      reflections?: string;
      observations?: string;
      project_notes?: string;
      user_context?: string;
      technical_insights?: string;
      world_knowledge?: string;
    },
    timestamp: Date,
    basePath: string
  ): Promise<void> {
    const dateString = this.formatDate(timestamp);
    const timeString = this.formatTimestamp(timestamp);

    const dayDirectory = path.join(basePath, dateString);
    const fileName = `${timeString}.md`;
    const filePath = path.join(dayDirectory, fileName);

    await this.ensureDirectoryExists(dayDirectory);

    const formattedEntry = this.formatThoughts(thoughts, timestamp);
    await fs.writeFile(filePath, formattedEntry, 'utf8');

    // Generate and save embedding
    await this.generateEmbeddingForEntry(filePath, formattedEntry, timestamp);
  }

  private formatThoughts(thoughts: {
    reflections?: string;
    observations?: string;
    project_notes?: string;
    user_context?: string;
    technical_insights?: string;
    world_knowledge?: string;
  }, timestamp: Date): string {
    const timeDisplay = timestamp.toLocaleTimeString('en-US', { 
      hour12: true, 
      hour: 'numeric', 
      minute: '2-digit', 
      second: '2-digit' 
    });
    const dateDisplay = timestamp.toLocaleDateString('en-US', { 
      year: 'numeric', 
      month: 'long', 
      day: 'numeric' 
    });

    const sections = [];

    if (thoughts.reflections) {
      sections.push(`## Reflections\n\n${thoughts.reflections}`);
    }

    if (thoughts.observations) {
      sections.push(`## Observations\n\n${thoughts.observations}`);
    }

    if (thoughts.project_notes) {
      sections.push(`## Project Notes\n\n${thoughts.project_notes}`);
    }

    if (thoughts.user_context) {
      sections.push(`## User Context\n\n${thoughts.user_context}`);
    }

    if (thoughts.technical_insights) {
      sections.push(`## Technical Insights\n\n${thoughts.technical_insights}`);
    }

    if (thoughts.world_knowledge) {
      sections.push(`## World Knowledge\n\n${thoughts.world_knowledge}`);
    }

    return `---
title: "${timeDisplay} - ${dateDisplay}"
date: ${timestamp.toISOString()}
timestamp: ${timestamp.getTime()}
---

${sections.join('\n\n')}
`;
  }

  private async generateEmbeddingForEntry(
    filePath: string,
    content: string,
    timestamp: Date
  ): Promise<void> {
    try {
      const { text, sections } = this.embeddingService.extractSearchableText(content);

      if (text.trim().length === 0) {
        return; // Skip empty entries
      }

      const embedding = await this.embeddingService.generateEmbedding(text);

      const embeddingData: EmbeddingData = {
        embedding,
        text,
        sections,
        timestamp: timestamp.getTime(),
        path: filePath
      };

      await this.embeddingService.saveEmbedding(filePath, embeddingData);
    } catch (error) {
      console.error(`Failed to generate embedding for ${filePath}:`, error);
      // Don't throw - embedding failure shouldn't prevent journal writing
    }
  }

  async generateMissingEmbeddings(): Promise<number> {
    let count = 0;
    const paths = [this.projectJournalPath, this.userJournalPath];

    for (const basePath of paths) {
      try {
        const dayDirs = await fs.readdir(basePath);

        for (const dayDir of dayDirs) {
          const dayPath = path.join(basePath, dayDir);
          const stat = await fs.stat(dayPath);

          if (!stat.isDirectory() || !dayDir.match(/^\d{4}-\d{2}-\d{2}$/)) {
            continue;
          }

          const files = await fs.readdir(dayPath);
          const mdFiles = files.filter(file => file.endsWith('.md'));

          for (const mdFile of mdFiles) {
            const mdPath = path.join(dayPath, mdFile);
            const embeddingPath = mdPath.replace(/\.md$/, '.embedding');

            try {
              await fs.access(embeddingPath);
              // Embedding already exists, skip
            } catch {
              // Generate missing embedding
              console.error(`Generating missing embedding for ${mdPath}`);
              const content = await fs.readFile(mdPath, 'utf8');
              const timestamp = this.extractTimestampFromPath(mdPath) || new Date();
              await this.generateEmbeddingForEntry(mdPath, content, timestamp);
              count++;
            }
          }
        }
      } catch (error) {
        if ((error as NodeJS.ErrnoException)?.code !== 'ENOENT') {
          console.error(`Failed to scan ${basePath} for missing embeddings:`, error);
        }
      }
    }

    return count;
  }

  private extractTimestampFromPath(filePath: string): Date | null {
    const filename = path.basename(filePath, '.md');
    const match = filename.match(/^(\d{2})-(\d{2})-(\d{2})-\d{6}$/);

    if (!match) return null;

    const [, hours, minutes, seconds] = match;
    const dirName = path.basename(path.dirname(filePath));
    const dateMatch = dirName.match(/^(\d{4})-(\d{2})-(\d{2})$/);

    if (!dateMatch) return null;

    const [, year, month, day] = dateMatch;
    return new Date(parseInt(year), parseInt(month) - 1, parseInt(day), 
                   parseInt(hours), parseInt(minutes), parseInt(seconds));
  }

  private async ensureDirectoryExists(dirPath: string): Promise<void> {
    try {
      await fs.access(dirPath);
    } catch (error) {
      try {
        await fs.mkdir(dirPath, { recursive: true });
      } catch (mkdirError) {
        throw new Error(`Failed to create journal directory at ${dirPath}: ${mkdirError instanceof Error ? mkdirError.message : mkdirError}`);
      }
    }
  }
}
